#include <cstdio>
#include <vector>

struct Frame {
    int vertex;
    int edge;
};

int main() {
    int n, m;
    if (scanf("%d%d", &n, &m) != 2) return 0;

    std::vector<int> head(n + 1, -1);
    std::vector<int> to(2 * m);
    std::vector<int> next(2 * m);

    for (int i = 0; i < m; ++i) {
        int u, v;
        scanf("%d%d", &u, &v);

        int e = 2 * i;
        to[e] = v;
        next[e] = head[u];
        head[u] = e;

        to[e + 1] = u;
        next[e + 1] = head[v];
        head[v] = e + 1;
    }

    std::vector<unsigned char> out(n + 1, 0);
    std::vector<Frame> stack;
    stack.reserve(n);

    for (int start = 1; start <= n; ++start) {
        stack.clear();
        stack.push_back({start, -2});

        while (!stack.empty()) {
            Frame &frame = stack.back();
            int x = frame.vertex;

            if (frame.edge == -2) {
                int same = 0;
                for (int e = head[x]; e != -1; e = next[e]) {
                    if (out[to[e]] == out[x]) ++same;
                }

                if (same <= 1) {
                    stack.pop_back();
                    continue;
                }

                out[x] ^= 1;
                frame.edge = head[x];
            } else if (frame.edge == -1) {
                stack.pop_back();
            } else {
                int e = frame.edge;
                frame.edge = next[e];
                stack.push_back({to[e], -2});
            }
        }
    }

    for (int i = 1; i <= n; ++i)
        putchar('0' + out[i]);

    return 0;
}

