#endif

int u[maxn * 2], v[maxn * 2], head[maxn], next[maxn * 2];
int out[maxn];
int n, m;

void dfs(int x)
{
    int c0 = 0;
    for (int i = head[x]; i != -1; i = next[i])
    {
        if (out[v[i]] == out[x])
            c0++;
    }

    if (c0 > 1)
    {
        out[x] ^= 1;
        for (int i = head[x]; i != -1; i = next[i])
            dfs(v[i]);
    }
}

