#include <cstdio>
#include <vector>
#include <queue>

int main() {
    int n, m;
    if (scanf("%d%d", &n, &m) != 2) return 0;

    std::vector<int> head(n + 1, -1);
    std::vector<int> to(2 * m);
    std::vector<int> next(2 * m);

    int edgeCount = 0;
    for (int i = 0; i < m; ++i) {
        int u, v;
        scanf("%d%d", &u, &v);

        to[edgeCount] = v;
        next[edgeCount] = head[u];
        head[u] = edgeCount++;

        to[edgeCount] = u;
        next[edgeCount] = head[v];
        head[v] = edgeCount++;
    }

    std::vector<int> out(n + 1, 0);
    std::vector<char> queued(n + 1, true);
    std::queue<int> q;

    for (int i = 1; i <= n; ++i) q.push(i);

    while (!q.empty()) {
        int x = q.front();
        q.pop();
        queued[x] = false;

        int same = 0;
        for (int e = head[x]; e != -1; e = next[e]) {
            if (out[to[e]] == out[x]) ++same;
        }

        if (same > 1) {
            out[x] ^= 1;
            for (int e = head[x]; e != -1; e = next[e]) {
                int y = to[e];
                if (!queued[y]) {
                    queued[y] = true;
                    q.push(y);
                }
            }
        }
    }

    for (int i = 1; i <= n; ++i) {
        printf("%d", out[i]);
    }
    return 0;
}

